    private void initOverlay() {
        glassPane = new JPanel(new BorderLayout()) {
            @Override
            protected void paintComponent(java.awt.Graphics g) {
                java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
                g2.setColor(new java.awt.Color(0, 0, 0, 120));
                g2.fillRect(0, 0, getWidth(), getHeight());
                g2.dispose();
            }
        };
        glassPane.setOpaque(false);
        overlayProgress = new JProgressBar();
        overlayProgress.setIndeterminate(true);
        overlayProgress.setStringPainted(true);
        overlayProgress.setString("Loading...");
        JPanel center = new JPanel(new java.awt.GridBagLayout());
        center.setOpaque(false);
        center.add(overlayProgress);
        glassPane.add(center, BorderLayout.CENTER);
        setGlassPane(glassPane);
    }

    private void showOverlay(boolean show) {
        if (glassPane == null) {
            return;
        }
        glassPane.setVisible(show);
        glassPane.repaint();
    }

    private void setupOverlayProgress(int total) {
        if (overlayProgress == null) {
            return;
        }
        overlayProgress.setIndeterminate(false);
        overlayProgress.setMinimum(0);
        overlayProgress.setMaximum(Math.max(1, total));
        overlayProgress.setValue(0);
        overlayProgress.setString("Loading tree: 0/" + total);
    }

    private void updateOverlayProgress(int done, int total) {
        if (overlayProgress == null) {
            return;
        }
        overlayProgress.setMaximum(Math.max(1, total));
        overlayProgress.setValue(done);
        overlayProgress.setString("Loading tree: " + done + "/" + total);
    }

    private void initTreeListener() {
        tree.addTreeSelectionListener(new TreeSelectionListener() {
            @Override
            public void valueChanged(TreeSelectionEvent event) {
                TreePath path = event.getPath();
                if (path == null) {
                    return;
                }
                Object nodeObj = ((DefaultMutableTreeNode) path.getLastPathComponent()).getUserObject();
                if (nodeObj instanceof NodeData data) {
                    if (data.getType() == NodeType.CLASS || data.getType() == NodeType.CLASS_IN_JAR) {
                        currentSelection = data;
                        decompileSelection(data);
                    }
                }
            }
        });
    }

    private void initTreeRenderer() {
        DefaultTreeCellRenderer renderer = new DefaultTreeCellRenderer() {
            private final Icon classIcon = new ClassKindIcon(new java.awt.Color(76, 141, 246), "C");
            private final Icon interfaceIcon = new ClassKindIcon(new java.awt.Color(60, 179, 113), "I");
            private final Icon enumIcon = new ClassKindIcon(new java.awt.Color(240, 173, 78), "E");

            @Override
            public java.awt.Component getTreeCellRendererComponent(JTree tree, Object value, boolean sel, boolean expanded,
                                                                   boolean leaf, int row, boolean hasFocus) {
                java.awt.Component component = super.getTreeCellRendererComponent(tree, value, sel, expanded, leaf, row, hasFocus);
                if (value instanceof DefaultMutableTreeNode node) {
                    Object userObject = node.getUserObject();
                    if (userObject instanceof NodeData data && data.getClassKind() != null) {
                        switch (data.getClassKind()) {
                            case INTERFACE -> setIcon(interfaceIcon);
                            case ENUM -> setIcon(enumIcon);
                            default -> setIcon(classIcon);
                        }
                    }
                }
                return component;
            }
        };
        tree.setCellRenderer(renderer);
    }

