    private void initEngineCombo() {
        DefaultComboBoxModel<DecompilerEngine> model = new DefaultComboBoxModel<>();
        for (DecompilerEngine engine : engineRegistry.getEngines()) {
            model.addElement(engine);
        }
        engineCombo.setModel(model);
        engineCombo.setRenderer((list, value, index, isSelected, cellHasFocus) -> {
            JLabel label = new JLabel();
            if (value != null) {
                label.setText(value.getDisplayName());
            }
            if (isSelected) {
                label.setOpaque(true);
                label.setBackground(list.getSelectionBackground());
                label.setForeground(list.getSelectionForeground());
            }
            return label;
        });
    }

