    private void chooseDirectory() {
        JFileChooser chooser = new JFileChooser();
        chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
        int result = chooser.showOpenDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            Path dir = chooser.getSelectedFile().toPath();
            scanDirectory(dir);
        }
    }

    private void rescan() {
        if (currentDirectory == null) {
            chooseDirectory();
            return;
        }
        scanDirectory(currentDirectory);
    }

    private void scanDirectory(Path directory) {
        currentDirectory = directory;
        statusLabel.setText("Directory: " + directory);
        codeArea.setText("");
        cache.clear();
        SwingWorker<IndexModel, Void> worker = new SwingWorker<>() {
            @Override
            protected IndexModel doInBackground() throws Exception {
                JarScanner scanner = new JarScanner();
                return IndexBuilder.build(scanner.scan(directory));
            }

            @Override
            protected void done() {
                try {
                    indexModel = get();
                    refreshTree();
                    statusLabel.setText("Scan complete: " + indexModel.getJars().size() + " JAR(s)");
                } catch (Exception e) {
                    statusLabel.setText("Scan failed: " + e.getMessage());
                }
            }
        };
        worker.execute();
    }

    private void refreshTree() {
        if (indexModel == null) {
            return;
        }
        showOverlay(true);
        int total = viewModeCombo.getSelectedIndex() == 0
            ? indexModel.getJars().stream().mapToInt(jar -> jar.getClassInternalNames().size()).sum()
            : indexModel.getClassesByInternalName().size();
        setupOverlayProgress(total);
        SwingWorker<DefaultMutableTreeNode, Void> worker = new SwingWorker<>() {
            @Override
            protected DefaultMutableTreeNode doInBackground() {
                ProgressListener listener = (done, max) -> SwingUtilities.invokeLater(() -> updateOverlayProgress(done, max));
                return viewModeCombo.getSelectedIndex() == 0
                    ? treeBuilder.buildByJar(indexModel, listener)
                    : treeBuilder.buildByClass(indexModel, listener);
            }

            @Override
            protected void done() {
                try {
                    DefaultMutableTreeNode root = get();
                    tree.setModel(new DefaultTreeModel(root));
                    expandTopLevel();
                    applyPendingSelection();
                } catch (Exception e) {
                    statusLabel.setText("Tree build failed: " + e.getMessage());
                } finally {
                    showOverlay(false);
                }
            }
        };
        worker.execute();
    }

    private void expandTopLevel() {
        for (int i = 0; i < tree.getRowCount() && i < 20; i++) {
            tree.expandRow(i);
        }
    }

    private void decompileSelection(NodeData data) {
        if (data.getJarPath() == null || data.getInternalName() == null) {
            return;
        }
        DecompilerEngine engine = (DecompilerEngine) engineCombo.getSelectedItem();
        if (engine == null) {
            return;
        }
        Charset charset = (Charset) charsetCombo.getSelectedItem();
        String cached = cache.get(engine.getId(), data.getJarPath(), data.getInternalName());
        if (cached != null) {
            codeArea.setText(applyEncoding(cached, charset));
            codeArea.setCaretPosition(0);
            if (pendingScrollInternal != null && pendingScrollInternal.equals(data.getInternalName())) {
                if (pendingScrollToken != null) {
                    Integer line = findLineByToken(pendingScrollType, pendingScrollToken);
                    if (line != null) {
                        scrollToLine(line);
                    } else if (pendingScrollLine != null) {
                        scrollToLine(pendingScrollLine);
                    }
                } else if (pendingScrollLine != null) {
                    scrollToLine(pendingScrollLine);
                }
                pendingScrollInternal = null;
                pendingScrollLine = null;
                pendingScrollType = null;
                pendingScrollToken = null;
            }
            return;
        }

        long currentId = requestId.incrementAndGet();
        statusLabel.setText("Decompiling: " + data.getInternalName());
        codeArea.setText("// Decompiling...\n");
        CompletableFuture<DecompileResult> future = executor.submit(() -> {
            try {
                String source = engine.decompile(data.getJarPath(), data.getInternalName(), StandardCharsets.UTF_8);
                SourceIndex index = SourceIndexBuilder.build(source);
                return new DecompileResult(source, index);
            } catch (Exception e) {
                return new DecompileResult("// Decompile failed: " + e.getMessage(), null);
            }
        });
        future.thenAccept(result -> SwingUtilities.invokeLater(() -> {
            if (requestId.get() != currentId) {
                return;
            }
            cache.put(engine.getId(), data.getJarPath(), data.getInternalName(), result.source());
            sourceIndexCache.put(engine.getId(), data.getJarPath(), data.getInternalName(), result.index());
            codeArea.setText(applyEncoding(result.source(), charset));
            codeArea.setCaretPosition(0);
            updateStructure(data);
            if (pendingScrollInternal != null && pendingScrollInternal.equals(data.getInternalName())) {
                if (pendingScrollToken != null) {
                    Integer line = findLineByToken(pendingScrollType, pendingScrollToken);
                    if (line != null) {
                        scrollToLine(line);
                    } else if (pendingScrollLine != null) {
                        scrollToLine(pendingScrollLine);
                    }
                } else if (pendingScrollLine != null) {
                    scrollToLine(pendingScrollLine);
                }
                pendingScrollInternal = null;
                pendingScrollLine = null;
                pendingScrollType = null;
                pendingScrollToken = null;
            }
            statusLabel.setText("Done: " + data.getInternalName());
        }));
    }


