    private void openSearchResult(SearchResult result) {
        if (result == null) {
            return;
        }
        if ("Resource".equals(result.getType())) {
            openResource(result);
            return;
        }
        if (result.getJarPath() == null || result.getInternalName() == null) {
            return;
        }
        NodeData data = new NodeData(NodeType.CLASS, result.getInternalName(), result.getJarPath(), result.getInternalName());
        currentSelection = data;
        Integer line = result.getLineNumber();
        pendingScrollInternal = result.getInternalName();
        if (line != null && line > 0) {
            pendingScrollLine = line;
        } else {
            pendingScrollType = result.getType();
            if ("Class".equals(result.getType())) {
                pendingScrollToken = simpleNameFromInternal(result.getInternalName());
            } else {
                pendingScrollToken = result.getMemberOrPath();
            }
        }
        decompileSelection(data);
    }

    private void openUsageResult(UsageResult result) {
        if (result == null || result.getJarPath() == null || result.getInternalName() == null) {
            return;
        }
        NodeData data = new NodeData(NodeType.CLASS, result.getInternalName(), result.getJarPath(), result.getInternalName());
        currentSelection = data;
        pendingScrollInternal = result.getInternalName();
        pendingScrollType = result.getKind();
        pendingScrollToken = result.getToken();
        Integer line = result.getLineNumber();
        if (line != null && line > 0) {
            pendingScrollLine = line;
        }
        decompileSelection(data);
    }

    private void openResource(SearchResult result) {
        if (result.getJarPath() == null || result.getMemberOrPath() == null) {
            return;
        }
        Charset charset = (Charset) charsetCombo.getSelectedItem();
        if (charset == null) {
            charset = StandardCharsets.UTF_8;
        }
        try (java.util.zip.ZipFile zip = new java.util.zip.ZipFile(result.getJarPath().toFile())) {
            java.util.zip.ZipEntry entry = zip.getEntry(result.getMemberOrPath());
            if (entry == null) {
                return;
            }
            byte[] bytes = zip.getInputStream(entry).readAllBytes();
            String text = new String(bytes, charset);
            codeArea.setText(text);
            codeArea.setCaretPosition(0);
            updateStructure(null);
            statusLabel.setText("Resource: " + result.getMemberOrPath());
        } catch (Exception e) {
            statusLabel.setText("Resource open failed: " + e.getMessage());
        }
    }

    private void scrollToLine(int lineNumber) {
        try {
            int line = Math.max(1, lineNumber);
            int offset = codeArea.getLineStartOffset(line - 1);
            codeArea.setCaretPosition(offset);
        } catch (Exception ignored) {
            // ignore
        }
    }

    private Integer findLineByToken(String type, String name) {
        if (type == null || name == null || name.isBlank()) {
            return null;
        }
        SourceIndex index = getCurrentSourceIndex();
        if (index != null) {
            Integer line = index.findLine(type, name);
            if (line != null) {
                return line;
            }
        }
        String text = codeArea.getText();
        if (text == null || text.isEmpty()) {
            return null;
        }
        Pattern pattern;
        if ("Method".equals(type)) {
            pattern = Pattern.compile("(?m)^(\\s*(public|protected|private|static|final|synchronized|abstract|native|strictfp)\\s+)*[\\w\\<\\>\\[\\]]+\\s+" + Pattern.quote(name) + "\\s*\\(");
        } else if ("Field".equals(type)) {
            pattern = Pattern.compile("(?m)^(\\s*(public|protected|private|static|final|transient|volatile)\\s+)*[\\w\\<\\>\\[\\]]+\\s+" + Pattern.quote(name) + "\\b.*;");
        } else if ("Class".equals(type)) {
            pattern = Pattern.compile("(?m)\\b(class|interface|enum)\\s+" + Pattern.quote(name) + "\\b");
        } else {
            pattern = Pattern.compile("(?m)\\b" + Pattern.quote(name) + "\\b");
        }
        Matcher matcher = pattern.matcher(text);
        if (matcher.find()) {
            int indexPos = matcher.start();
            return text.substring(0, indexPos).split("\\R", -1).length;
        }
        return null;
    }

    private String parseDescriptorParams(String descriptor) {
        if (descriptor == null || descriptor.isEmpty()) {
            return "";
        }
        int start = descriptor.indexOf('(');
        int end = descriptor.indexOf(')');
        if (start < 0 || end <= start) {
            return "";
        }
        String desc = descriptor.substring(start + 1, end);
        if (desc.isEmpty()) {
            return "";
        }
        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < desc.length()) {
            int arrayDim = 0;
            while (i < desc.length() && desc.charAt(i) == '[') {
                arrayDim++;
                i++;
            }
            if (i >= desc.length()) {
                break;
            }
            char c = desc.charAt(i);
            String type;
            if (c == 'L') {
                int semi = desc.indexOf(';', i);
                if (semi < 0) {
                    break;
                }
                String name = desc.substring(i + 1, semi);
                int lastSlash = name.lastIndexOf('/');
                type = lastSlash >= 0 ? name.substring(lastSlash + 1) : name;
                i = semi + 1;
            } else {
                type = switch (c) {
                    case 'I' -> "int";
                    case 'J' -> "long";
                    case 'Z' -> "boolean";
                    case 'B' -> "byte";
                    case 'C' -> "char";
                    case 'S' -> "short";
                    case 'F' -> "float";
                    case 'D' -> "double";
                    case 'V' -> "void";
                    default -> "";
                };
                i++;
            }
            if (type.isEmpty()) {
                continue;
            }
            if (arrayDim > 0) {
                type += "[]".repeat(arrayDim);
            }
            if (result.length() > 0) {
                result.append(",");
            }
            result.append(type);
        }
        return result.toString();
    }

    private SourceIndex getCurrentSourceIndex() {
        if (currentSelection == null) {
            return null;
        }
        DecompilerEngine engine = (DecompilerEngine) engineCombo.getSelectedItem();
        if (engine == null) {
            return null;
        }
        return sourceIndexCache.get(engine.getId(), currentSelection.getJarPath(), currentSelection.getInternalName());
    }

    private UsageKind inferUsageKind(String name) {
        for (StructureEntry entry : lastStructureEntries) {
            if (name.equals(entry.getName())) {
                if ("Field".equals(entry.getKind())) {
                    return UsageKind.FIELD;
                }
                if ("Method".equals(entry.getKind())) {
                    return UsageKind.METHOD;
                }
            }
        }
        if (Character.isUpperCase(name.charAt(0)) || name.contains(".")) {
            return UsageKind.CLASS;
        }
        return UsageKind.METHOD;
    }

    private String parseSelectedParams(String selected) {
        if (selected == null) {
            return "";
        }
        int start = selected.indexOf('(');
        int end = selected.lastIndexOf(')');
        if (start < 0 || end <= start) {
            return "";
        }
        String inside = selected.substring(start + 1, end).trim();
        if (inside.isEmpty()) {
            return "";
        }
        String cleaned = inside.replaceAll("<[^>]+>", "");
        cleaned = cleaned.replaceAll("\\bfinal\\b", "");
        cleaned = cleaned.replaceAll("@\\w+", "");
        cleaned = cleaned.replaceAll("\\s+", " ").trim();
        if (cleaned.isEmpty()) {
            return "";
        }
        String[] parts = cleaned.split(",");
        StringBuilder builder = new StringBuilder();
        for (String part : parts) {
            String p = part.trim();
            if (p.isEmpty()) {
                continue;
            }
            String[] tokens = p.split(" ");
            if (tokens.length > 0) {
                String type = tokens[0];
                if (builder.length() > 0) {
                    builder.append(",");
                }
                builder.append(type);
            }
        }
        return builder.toString();
    }

