    private void updateStructure(NodeData data) {
        if (!showStructureBox.isSelected()) {
            return;
        }
        if (data == null || data.getJarPath() == null || data.getInternalName() == null) {
            structurePanel.setEntries(java.util.Collections.emptyList());
            return;
        }
        executor.submit(() -> {
            List<StructureEntry> entries = new ArrayList<>();
            try {
                byte[] bytes = com.karlin.decompiler.core.JarClassReader.readClassBytes(data.getJarPath(), data.getInternalName());
                ClassReader reader = new ClassReader(bytes);
                reader.accept(new ClassVisitor(Opcodes.ASM9) {
                    @Override
                    public FieldVisitor visitField(int access, String name, String descriptor, String signature, Object value) {
                        entries.add(new StructureEntry("Field", name, descriptor, null));
                        return super.visitField(access, name, descriptor, signature, value);
                    }

                    @Override
                    public MethodVisitor visitMethod(int access, String name, String descriptor, String signature, String[] exceptions) {
                        return new MethodVisitor(Opcodes.ASM9) {
                            private Integer line;

                            @Override
                            public void visitLineNumber(int lineNumber, org.objectweb.asm.Label start) {
                                if (line == null) {
                                    line = lineNumber;
                                }
                            }

                            @Override
                            public void visitEnd() {
                                entries.add(new StructureEntry("Method", name, descriptor, line));
                            }
                        };
                    }
                }, ClassReader.SKIP_FRAMES);
            } catch (Exception ignored) {
                // ignore
            }
        structurePanel.setEntries(entries);
        lastStructureEntries = entries;
        return null;
    });
}

    private void jumpToStructure(StructureEntry entry) {
        if (entry == null) {
            return;
        }
        Integer line = entry.getLineNumber();
        String name = entry.getName();
        if (name == null || name.isBlank()) {
            return;
        }
        String token = name;
        if ("Method".equals(entry.getKind())) {
            String params = parseDescriptorParams(entry.getDescriptor());
            token = name + "(" + params + ")";
        }
        Integer sourceLine = findLineByToken(entry.getKind(), token);
        if (sourceLine != null) {
            scrollToLine(sourceLine);
            return;
        }
        if (line != null) {
            scrollToLine(line);
        }
    }

